def amicable_numbers_sum(limit):
    def proper_divisor_sum(n):
        total = 0
        for i in range(1, int(n ** 0.5) + 1):
            if n % i == 0:
                if i * i == n:
                    total += i
                else:
                    total += i + n // i
        return total - n

    amicable = set()
    for n in range(1, limit + 1):
        s = proper_divisor_sum(n)
        if s != n and proper_divisor_sum(s) == n:
            amicable.add(n)
    return sum(amicable)
```

