def max_sum_increasing_subseq(arr, n, i, k):
    dp = [0] * (i + 1)
    for j in range(i + 1):
        if arr[j] >= arr[k]:
            continue
        best = 0
        for l in range(j):
            if arr[l] < arr[j] and dp[l] > best:
                best = dp[l]
        dp[j] = best + arr[j]
    return max(dp) + arr[k]
